content.content:
1	//! Migration — legacy on-disk shapes to current.
2	//!
3	//! Converts:
4	//! - config.toml (`[validation]`/`[skills]` → storage-config)
5	//! - terminology.csv → lexicon.csv (related_terms → aliases)
6	//! - attractors.csv (valence/phase_state → positive_state/negative_state)
7	
8	use anyhow::{bail, Context, Result};
9	use serde::Deserialize;
10	use std::fs;
11	use std::path::Path;
12	
13	use crate::storage::config::StorageConfig;
14	use crate::storage::format::{self, write_attractors_v3};
15	use crate::structure::analysis::attractors::Attractor as V3Attractor;
16	use crate::structure::definition::lexicon::Term as LexiconTerm;
17	
18	#[derive(Debug, Clone)]
19	pub struct MigratedV3 {
20	    pub format_version: String,
21	    pub storage: StorageConfig,
22	    pub toml: String,
23	}
24	
25	#[derive(Debug, Clone, Default)]
26	pub struct MigrateReport {
27	    pub config_migrated: bool,
28	    pub attractors: usize,
29	    pub lexicon_terms: usize,
30	}
31	
32	#[derive(Debug, Deserialize)]
33	struct NaiveDocument {
34	    #[serde(default)]
35	    validation: NaiveValidation,
36	    #[serde(default)]
37	    skills: NaiveSkills,
38	}
39	
40	#[derive(Debug, Default, Deserialize)]
41	struct NaiveValidation {
42	    #[serde(default = "default_true")]
43	    strict: bool,
44	}
45	
46	#[derive(Debug, Default, Deserialize)]
47	struct NaiveSkills {
48	    #[serde(default = "default_token_warn")]
49	    token_warn: usize,
50	}
51	
52	fn default_true() -> bool {
53	    true
54	}
55	fn default_token_warn() -> usize {
56	    1000
57	}
58	
59	/// Convert naive config.toml (`[validation]` / `[skills]`) into v3 TOML.
60	pub fn migrate_naive_to_v3(naive_toml: &str) -> Result<MigratedV3> {
61	    let naive: NaiveDocument =
62	        toml::from_str(naive_toml).with_context(|| "parse naive config.toml")?;
63	    let storage = StorageConfig {
64	        format_version: "v3".to_string(),
65	        change_detection: true,
66	        super_strict: naive.validation.strict,
67	        token_warn: naive.skills.token_warn,
68	        commit_msg_enforce: false,
69	    };
70	    let toml_out = crate::storage::config::render_v3(&storage);
71	    Ok(MigratedV3 {
72	        format_version: storage.format_version.clone(),
73	        storage,
74	        toml: format!(
75	            "# residual v3 configuration (migrated from naive)\n{}",
76	            toml_out.trim_start_matches("# residual v3 configuration\n")
77	        ),
78	    })
79	}
80	
81	fn is_v3_config(raw: &str) -> bool {
82	    raw.contains("format_version") || raw.contains("[verification]") || raw.contains("[storage]")
83	}
84	
85	fn load_naive_attractors(path: &Path) -> Result<Vec<(String, String, String, String, String)>> {
86	    // id, name, valence, description, phase_state
87	    let mut rdr = csv::ReaderBuilder::new().has_headers(true).from_path(path)?;
88	    let mut rows = Vec::new();
89	    for rec in rdr.records() {
90	        let rec = rec?;
91	        rows.push((
92	            rec.get(0).unwrap_or("").to_string(),
93	            rec.get(1).unwrap_or("").to_string(),
94	            rec.get(2).unwrap_or("").to_string(),
95	            rec.get(3).unwrap_or("").to_string(),
96	            rec.get(4).unwrap_or("").to_string(),
97	        ));
98	    }
99	    Ok(rows)
100	}
101	
102	fn migrate_attractor_row(
103	    id: String,
104	    name: String,
105	    valence: &str,
106	    description: String,
107	    phase_state: String,
108	) -> V3Attractor {
109	    let (positive_state, negative_state) = match valence.to_lowercase().as_str() {
110	        "positive" => {
111	            let pos = if phase_state.is_empty() {
112	                description.clone()
113	            } else {
114	                phase_state
115	            };
116	            let neg = if description.is_empty() {
117	                format!("(migrated) pressure fails for {name}")
118	            } else {
119	                format!("(migrated) pressure fails when: {description}")
120	            };
121	            (pos, neg)
122	        }
123	        "negative" => {
124	            let neg = if phase_state.is_empty() {
125	                description.clone()
126	            } else {
127	                phase_state
128	            };
129	            let pos = if description.is_empty() {
130	                format!("(migrated) pressure holds for {name}")
131	            } else {
132	                format!("(migrated) pressure holds when opposite of: {description}")
133	            };
134	            (pos, neg)
135	        }
136	        _ => {
137	            let pos = if phase_state.is_empty() {
138	                format!("(migrated) positive state for {name}")
139	            } else {
140	                phase_state
141	            };
142	            let neg = if description.is_empty() {
143	                format!("(migrated) negative state for {name}")
144	            } else {
145	                description.clone()
146	            };
147	            (pos, neg)
148	        }
149	    };
150	    V3Attractor {
151	        id,
152	        name,
153	        description,
154	        positive_state,
155	        negative_state,
156	    }
157	}
158	
159	/// Migrate a residual/ directory to current on-disk shape.
160	pub fn migrate_residual_dir(residual_dir: &Path, force: bool) -> Result<MigrateReport> {
161	    if !residual_dir.is_dir() {
162	        bail!("residual dir not found: {}", residual_dir.display());
163	    }
164	
165	    let session = crate::storage::integrity::sessions::begin_mutation(residual_dir, force)?;
166	    let mut report = MigrateReport::default();
167	
168	    // --- config ---
169	    let config_path = residual_dir.join("config.toml");
170	    if config_path.exists() {
171	        let raw = fs::read_to_string(&config_path)?;
172	        if !is_v3_config(&raw) {
173	            let migrated = migrate_naive_to_v3(&raw)?;
174	            fs::write(&config_path, &migrated.toml)?;
175	            report.config_migrated = true;
176	        }
177	    } else {
178	        let cfg = StorageConfig::default();
179	        fs::write(&config_path, crate::storage::config::render_v3(&cfg))?;
180	        report.config_migrated = true;
181	    }
182	
183	    // --- terminology.csv → lexicon.csv ---
184	    let terminology_path = residual_dir.join("terminology.csv");
185	    if terminology_path.exists() {
186	        #[derive(serde::Deserialize)]
187	        struct OldTerm {
188	            term: String,
189	            definition: String,
190	            domain: String,
191	            related_terms: String,
192	        }
193	        let mut rdr = csv::ReaderBuilder::new()
194	            .has_headers(true)
195	            .from_path(&terminology_path)?;
196	        let mut lexicon: Vec<LexiconTerm> = format::read_lexicon(residual_dir)?;
197	        let existing_terms: std::collections::HashSet<String> =
198	            lexicon.iter().map(|t| t.term.clone()).collect();
199	        let mut added = 0usize;
200	        for rec in rdr.deserialize() {
201	            let t: OldTerm = rec?;
202	            if !existing_terms.contains(&t.term) {
